import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"RaceVLA: VLA-based Racing Drone Navigation with Human-like Behaviour","description":"","frontmatter":{"title":"RaceVLA: VLA-based Racing Drone Navigation with Human-like Behaviour","arxiv":"2503.02572","date":"2025-03-04","authors":"Valerii Serpiva, Artem Lykov, Artyom Myshlyaev, Muhammad Haris Khan, Ali Alridha Abdulkarim, Oleg Sautenkov, Dzmitry Tsetserukou","categories":"cs.RO, cs.AI","topics":"无人机, 视觉语言动作模型, 泛化评测","outline":[2,2]},"headers":[],"relativePath":"papers/2503.02572.md","filePath":"papers/2503.02572.md","lastUpdated":null}'),e={name:"papers/2503.02572.md"};function l(i,s,r,m,o,c){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="racevla-vla-based-racing-drone-navigation-with-human-like-behaviour" tabindex="-1">RaceVLA: VLA-based Racing Drone Navigation with Human-like Behaviour <a class="header-anchor" href="#racevla-vla-based-racing-drone-navigation-with-human-like-behaviour" aria-label="Permalink to &quot;RaceVLA: VLA-based Racing Drone Navigation with Human-like Behaviour&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.02572" target="_blank" rel="noreferrer">2503.02572</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-04</td></tr><tr><td><strong>作者</strong></td><td>Valerii Serpiva, Artem Lykov, Artyom Myshlyaev, Muhammad Haris Khan, Ali Alridha Abdulkarim, Oleg Sautenkov, Dzmitry Tsetserukou</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把 OpenVLA-7B 的 7 维机械臂动作头改成无人机的 4 维速度指令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.044em;">z</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mclose">)</span></span></span></span>，在 200 条真机竞速飞行上 LoRA 微调，得到第一个端到端控制竞速无人机的 VLA。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 范式在机械臂上已经跑通：视觉与语言直接映射到控制信号，不经过显式的目标检测、轨迹生成或技能选择，换来的是对训练集之外任务的泛化能力。无人机侧的自主系统却基本停留在上一代结构——LLM/transformer 负责规划或高层指令，另有传统模块负责执行。这种分层结构在实时性与适应性上都有代价：模块间的接口固定了可表达的行为空间，遇到训练分布外的情况时，语言模型给出的高层指令未必能被下层执行器正确落地。</p><p>本文要回答的是一个存在性问题：<strong>能不能把 VLA 直接搬到高速、动态、相机随机体剧烈运动的无人机上</strong>。竞速无人机是这个问题的极端设定——需要连续穿门、避碰、在无停顿的情况下实时调整轨迹。如果 VLA 在这里能工作，那么&quot;通用无人机&quot;（一个模型执行多种飞行任务、包括未见过的任务）就有了可行路径；如果不能，问题出在哪一环也值得知道。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>机械臂侧的 PaLM-E、RT-1/RT-2/RT-X 确立了范式，OpenVLA 把微调门槛降到消费级硬件，MiniVLA 进一步压缩模型以便机载推理。这条线的全部经验建立在静止相机、准静态操作、7 维末端动作之上。</p><p>无人机侧已有工作分三类。<strong>空中视觉语言导航</strong>：AerialVLN 提出任务与数据集，Aerial Vision-and-Dialog Navigation 加入飞行中的人机对话，EmbodiedCity 做城市级具身环境，STMR 把地图编码成矩阵喂给 LLM，OpenUAV 提供平台与基准。这些工作的输出仍是导航决策或路径，不是控制信号。<strong>集群控制</strong>：SwarmGPT 为每架无人机生成轨迹，FlockGPT 用有符号距离函数定义飞行方向——同样停在轨迹层。<strong>深度强化学习竞速</strong>：已经达到冠军级水平，但策略绑定在特定赛道与任务上，不接受语言指令，也不具备语义泛化。</p><p>论文对这些工作的批评是统一的：它们聚焦于规划与轨迹生成，因此适应性与实时控制能力受限，难以泛化到预定义数据集之外的任务，也难以对突发情况快速反应。这个批评在方向上成立，但需要注意它同时也意味着<strong>本文与这些工作没有共同的评测协议</strong>——一个输出轨迹、一个输出速度指令，没有现成的公共基准可比。这一点将在 § 7 与 § 11 变得关键。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>2024 年末的既成条件很具体。OpenVLA 已开源、支持 LoRA 微调，其动作头是一个 7 维离散向量（3 平移增量 + 3 旋转增量 + 1 夹爪）。无人机在 ArduPilot 下的标准控制接口恰好是 4 维速度设定点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.044em;">z</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mclose">)</span></span></span></span>。两者在结构上是同类：都是低维、有界、可离散化的连续控制量。把 7 维换成 4 维，是一个极小的改动。</p><p>另一个观察是关于数据。机械臂 VLA 的一大痛点是相机静止，同一条 episode 内视觉多样性很低，模型容易过拟合背景；而无人机的机载 FPV 相机跟着机体走，单条 episode 内背景、物体位置、尺度都在剧烈变化。作者据此下了一个赌注：<strong>动态相机本身就是一种天然的数据增强</strong>，会让模型对相机位姿不敏感，从而在运动泛化上更好。这个赌注在 § 7 中被当作解释而非被检验。</p><p>第三个约束是算力。7B 模型无法机载实时推理，所以只能量化到 int8 放在地面工作站上，通过 API 与无人机通信——这决定了系统频率只能是个位数 Hz，进而决定了可行的飞行速度上限。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>VLA 从机械臂搬到无人机，真正需要换的只有动作头的维度；视觉-语言到控制的映射结构本身是通用的。而无人机相较机械臂还有两个结构性优势：动作空间更低维（4 维速度而非 7 维位姿加夹爪），任务是&quot;绕过/穿过&quot;而不是&quot;抓取/放置&quot;——没有接触动力学，也就没有精细力控的要求。因此在同等模型容量下，无人机 VLA 反而有更多余量用于语义理解与运动泛化。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以任务&quot;沿环形赛道穿过多个门&quot;为例。</p><ul><li><strong>模型</strong>：OpenVLA-7B，输入为机载 FPV 单帧图像 + 自然语言指令，输出改为 4 维 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.044em;">z</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mclose">)</span></span></span></span>。推理时不等无人机到达上一个目标点就处理下一帧——即连续闭环而非路点式停走，这对竞速的连贯性是必要的。</li><li><strong>数据</strong>：200 条 episode、约 20000 张图像，任务包括穿拱形门、穿方形门、环形赛道连续穿门。速度由 Vicon 动捕以 60 Hz 记录，T265 相机以 30 Hz 采图，每个样本含位置、速度分量、偏航角变化与同步图像。指令形如&quot;Fly through the arch gate&quot;。数据整理成 RLDS 格式。</li><li><strong>训练</strong>：LoRA rank-32，batch 16，lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>，7000 步，关闭图像增强以保留数据真实性，单张 A100，用 W&amp;B 监控 loss、动作预测准确率与 L1 loss。</li><li><strong>硬件与部署</strong>：自研 8 英寸竞速机，Speedy Bee F405 飞控跑 ArduPilot，经 MAVROS 通信；RealSense T265 作 FPV 相机；机载 Intel NUC 负责定位与控制，定位用 OpenVINS 视觉惯性里程计。模型 int8 量化后跑在地面 RTX 4090 上，单帧推理 0.25 s，经 Flask API 收发，系统频率 4 Hz。全系统在 ROS 下运行。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。全文唯一的形式化内容是动作向量的重定义——把 OpenVLA 原本的 7 维输出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">Δ</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal">ϕ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0359em;">ψ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span></span></span></span> 替换为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.044em;">z</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mclose">)</span></span></span></span>，即从位姿增量控制改为速度控制，以匹配 ArduPilot 的速度设定点接口。训练目标、离散化方案与 LoRA 均沿用 OpenVLA 原文，论文未提出新的损失函数、约束或理论分析。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>飞行性能。</strong> 第一组测试覆盖单门穿越、按指令选门（左/右）、连续多门序列：平均速度 0.51 m/s、最高 0.80 m/s、速度标准差 0.17 m/s、平均偏航角速度 0.243 rad/s、任务平均时长 26.92 s。第二组是环形赛道三圈：平均速度约 1.04 m/s、最高 2.02 m/s、标准差 0.27 m/s，平均偏航角速度 0.40 rad/s（标准差 0.12）。</p><p>这一节必须点明一个缺口：<strong>全部指标都是运动学统计量，没有任何成功率</strong>。穿过多少扇门、失败多少次、从未见起点出发的完成率是多少，正文没有给出（图 5 展示了从不同起点出发的评测场景，但未给数值）。因此关于&quot;RaceVLA 能否可靠完成竞速任务&quot;这一最基本的问题，论文没有提供可核验的答案。</p><p><strong>泛化评测。</strong> 作者沿用 OpenVLA 的四轴框架（视觉、运动、物理、语义），在无人机任务上做了 200 次实验（图 6）。结果：相对 OpenVLA，运动 75.0 vs 60.0、语义 45.5 vs 36.3 更好；视觉 79.6 vs 87.0、物理 50.0 vs 76.7 更差。相对 RT-2 则四轴全面领先：视觉 79.6 vs 52.0、运动 75.0 vs 55.0、物理 50.0 vs 26.7、语义 45.5 vs 38.8。</p><p>作者对差异的解释是：动态相机在单条样本内提供了多样视觉输入，因而运动泛化更好；没有物体操作使运动动力学更简单，因而语义泛化也更好；反过来，无人机必须靠机动绕开干扰物而非仅靠视觉聚焦，且门的尺寸形状变化在飞行视角下因距离与运动而显得更小或畸变，因而视觉与物理泛化更差。</p><p>这些解释在内部是自洽的，但它们同时暴露了比较本身的问题：作者明确承认&quot;没有物体操作简化了运动动力学&quot;——也就是说，被比较的两组任务难度不同。§ 11 会把这条展开为主要攻击点。</p><p><strong>未做的实验。</strong> 没有与任何无人机方法（DRL 竞速策略、AerialVLN 类导航、或简单的 PID + 目标检测流水线）的直接比较；没有消融（不换动作头会怎样？不用语言指令会怎样？换更小的 MiniVLA 会怎样？）；没有报告推理延迟对成功率的影响曲线，而 4 Hz 与 1 m/s 的组合意味着每次决策间无人机已飞出约 26 cm。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：RaceVLA 把 OpenVLA-7B 的动作头从 7 维机械臂位姿改成 4 维无人机速度指令，在 200 条真机竞速 episode（约 2 万张图）上用 LoRA rank-32 微调，得到第一个端到端控制竞速无人机的 VLA。系统 int8 量化后在地面 RTX 4090 上以 4 Hz 运行，单帧推理 0.25 s，实测平均速度 1.04 m/s、最高 2.02 m/s。四轴泛化评测里，运动（75.0 vs 60.0）与语义（45.5 vs 36.3）优于 OpenVLA，视觉（79.6 vs 87.0）与物理（50.0 vs 76.7）低于 OpenVLA，四轴全面优于 RT-2。作者把运动泛化的优势归因于机载相机随机体运动带来的天然视觉多样性，同时承认无人机任务不含物体操作因而动力学更简单。全文没有报告任何穿门成功率，泛化对比的对手来自完全不同的任务套件与本体。</p><p><strong>3 句话版</strong>：VLA 从机械臂迁到无人机在工程上只需换动作头维度，这条路是通的。动态相机确实可能带来对相机位姿的不变性，这是无人机相对机械臂的结构性优势。但论文提供的证据是运动学统计量与跨本体跨任务的分数对比，不足以支撑&quot;优于 OpenVLA&quot;这类结论。</p><p><strong>1 句话版</strong>：把 OpenVLA 的夹爪换成油门，无人机 VLA 就跑起来了——但还没有人证明它飞得好。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>沿用 OpenVLA 的四轴泛化框架、在完全不同的任务与本体上得到的分数，可以与 OpenVLA/RT-2 的原始分数直接比较</strong>。全文最核心的定量结论（&quot;outperforms OpenVLA in motion and semantic generalization&quot;、&quot;outperforms RT-2 across all axes&quot;）完全建立在这条假设上。</p><p>它几乎肯定不成立。OpenVLA 与 RT-2 的这些分数来自桌面机械臂的抓取-放置任务套件，本文的分数来自 200 次无人机穿门实验；两者共享的只有&quot;视觉/运动/物理/语义&quot;这四个标签名，具体任务、成功判据、试验次数、本体全都不同。论文自己在解释结果时给出了最强的反证：&quot;RaceVLA 中不存在物体操作，简化了运动动力学，使模型在只需绕开新物体而非抓取它们的场景中表现出色&quot;——这句话直接说明了运动泛化上的优势来自任务更简单，而不是模型更强。同理，&quot;语义泛化更好&quot;也被归因于&quot;无需与物体做复杂物理交互&quot;。</p><p>论文为这条假设提供的证据是：评测&quot;遵循 OpenVLA 建立的实验框架，适配到无人机竞速的独特挑战，同时保持核心原则以便公平比较&quot;。这只是流程上的类比，不构成分数可比性的论证。缺的是最基本的东西——一个共同的对照：把 OpenVLA（或其无人机微调版）放到<strong>同一条赛道、同一组任务</strong>上跑一遍。没有这个，四轴表格只能读作&quot;RaceVLA 在自己的任务上的四类得分&quot;，不能读作与任何方法的比较。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内、不需要真机、不需要重新采数据，只验证一件事：<strong>语言指令在闭环中是否真的被使用</strong>。这是端到端 VLA 最容易被忽略也最容易证伪的性质。</p><ol><li>用作者开源的权重、数据集与仿真/回放环境（论文声明代码、权重、数据全部开源）。</li><li>在离线数据上构造三组推理：(a) 原始指令；(b) 指令替换为一句无关文本（如&quot;the weather is nice&quot;）；(c) 指令替换为与真值相反的指令（如把&quot;Fly through the Right gate&quot;换成&quot;Left gate&quot;）。</li><li>度量：三组输出动作向量的 L1 差异，以及在&quot;选门&quot;类样本（图 5b 的左/右门任务）上按指令方向偏转的比例。</li></ol><p>判据：若 (b) 与 (a) 的动作几乎相同，说明模型主要靠视觉惯性飞行、语言通道近乎惰性——那么&quot;语义泛化 45.5&quot;就需要重新解释；若 (c) 能可靠地把速度方向翻转，则语言确实进入了闭环，模型的语义能力得到独立于四轴表格的证据。这个实验成本极低，却是论文里完全缺失的、最能支撑其核心主张的证据。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释：泛化表格测量的是任务难度差异，不是模型能力差异。</strong> § 9 已论证这一点，这里给出可执行的证伪方案。把 OpenVLA 用<strong>完全相同的流水线</strong>（同样的 RLDS 格式、同样的 LoRA rank-32、同样的 7000 步、同样的 4 维动作头）在同一批 200 条数据上微调，得到 OpenVLA-drone；再让 RaceVLA 与 OpenVLA-drone 在同一组四轴任务上各跑 200 次。若两者分数接近，则&quot;RaceVLA 优于 OpenVLA&quot;实为&quot;无人机任务比机械臂任务简单&quot;，全文的定量主张需要撤回；若 RaceVLA 明显更好，则说明本文除动作头之外还有未被讲清的贡献。这个对照的成本与已做的实验相当，却是唯一能让比较成立的做法。</p><p><strong>可预测的失败条件：系统频率与飞行速度的乘积构成硬上限。</strong> 单帧推理 0.25 s、系统 4 Hz，意味着两次决策之间无人机在 1.04 m/s 下飞出约 26 cm、在 2.02 m/s 下飞出约 50 cm。竞速门的通径通常在 1 m 量级，所以当前速度已经接近&quot;一次错误决策就撞门&quot;的边界。作者在结论里也承认&quot;提速需要先降低推理时间&quot;。一个直接的反例实验：在同一赛道上逐步提高速度上限（1.0 → 1.5 → 2.0 → 3.0 m/s）并测量穿门成功率，预期会出现一个陡峭的崩塌点，且崩塌点位置与 4 Hz 成正比。这会把&quot;RaceVLA 能处理高速场景&quot;这一表述限定为&quot;能处理约 1 m/s 的场景&quot;——而人类竞速飞手的典型速度高一个数量级以上。</p><p><strong>第三点：论文没有给出穿门成功率，这使得所有正面结论都缺一个锚。</strong> 平均速度 1.04 m/s 这类统计量在无人机撞门后照样可以被算出来。要让&quot;RaceVLA 能飞完赛道&quot;成立，最低限度需要报告：每种任务的完成率、试验次数、以及失败模式分类。图 4 的三圈轨迹图是唯一的定性证据，而三圈不足以支撑任何可靠性结论。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：本文的架构是&quot;单帧输入 → 单步速度指令&quot;，把无人机当成一个反应式控制器。这有两个后果：模型没有任何速度或姿态的历史信息（4 Hz 下相邻帧间隔 0.25 s，视觉惯性无法从单帧恢复），也没有任何机制表达&quot;我打算沿这条弧线穿门&quot;这类跨越多个决策周期的意图。当推理延迟与飞行速度的乘积增大时，这种反应式结构必然失效——这不是把模型变快就能绕开的，而是表示形式的问题。</p><p><strong>(b) 可借鉴的相邻工具</strong>：<strong>微分平坦性（differential flatness）</strong>。四旋翼是微分平坦系统——整条动力学可由位置与偏航的四维平坦输出及其导数完全参数化。这意味着一段多项式（如 minimum-snap）轨迹与一段速度指令序列是等价的表示，但前者可以用极少的参数表达一段长时程意图，且天然满足动力学可行性。</p><p><strong>(c) 新 framing 与第一个实验</strong>：把 VLA 的输出从&quot;下一步速度&quot;改为&quot;下一段平坦输出多项式的系数&quot;——即让模型输出一小段轨迹的参数化表示，由机载控制器以数百 Hz 跟踪。这不是回到&quot;VLA 出高层指令、传统模块执行&quot;的老分层（那里的接口是离散的路点或技能标签），而是让 VLA 直接输出连续、动力学可行、可微的轨迹段：语义理解仍然端到端，但模型的每一次推理覆盖数百毫秒而非一帧，从根本上解耦了推理延迟与控制频率。同时这也让&quot;人类般的行为&quot;第一次可以被量化——人类飞手的轨迹在平坦空间里有可测的平滑度与激进程度特征，可以直接与模型输出对比。第一个实验：用同一批 200 条 Vicon 数据，把标签从逐帧速度改成每 0.5 s 一段的 minimum-snap 系数，同样 LoRA 微调；在 § 11 的变速赛道上对比两种输出形式的穿门成功率随速度上升的崩塌曲线。若轨迹输出版本的崩塌点显著后移，就说明当前的速度瓶颈来自表示形式而非模型规模，这与&quot;等更快的硬件&quot;是完全不同的结论。</p><p><strong>批内关联</strong>：同组随后的 <a href="/notes/papers/2503.01378">CognitiveDrone</a> 把 RaceVLA 当作基线，发现它在需要判断的选门任务上总分仅 31.3%、并自评为&quot;近乎随机&quot;。这与本文的观察一致——RaceVLA 的训练数据里所有指令都直接指明目标门的形状或方位，模型从未被要求做任何推断，因此它的&quot;语义泛化 45.5&quot;更可能反映的是对指令模板的匹配能力，而非语义理解。</p>',49)])])}const u=a(e,[["render",l]]);export{g as __pageData,u as default};
